'use strict';
function emptySVG(message){return `<svg viewBox="0 0 650 270" role="img" aria-label="${esc(message)}"><text x="325" y="130" text-anchor="middle" style="font-size:13px">${esc(message)}</text></svg>`;}
function chartSeries(rows,key,value,agg,grain){if(E.type(rows,key)==='date'){const k='__date_group';const mapped=rows.filter(r=>!E.missing(r[key])).map(r=>({...r,[k]:String(r[key]).slice(0,grain==='year'?4:grain==='day'?10:7)}));return E.group(mapped,k,value,agg).sort((a,b)=>String(a.key).localeCompare(String(b.key)));}return E.group(rows,key,value,agg);}
function svgStart(id,title,w=650,h=270){return `<svg id="${id}" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(title)}"><title>${esc(title)}</title>`;}
function shortNumber(n){if(Math.abs(n)>=1e6)return `${nf(n/1e6,1)}M`;if(Math.abs(n)>=1000)return `${nf(n/1000,1)}k`;return nf(n,1);}
function shortLabel(v,max=12){let s=display(v);if(/^\d{4}-\d{2}$/.test(String(v)))s=state.lang==='zh'?`${Number(String(v).slice(5))}月`:['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'][Number(String(v).slice(5))-1];return s.length>max?s.slice(0,max-1)+'…':s;}
function bounds(values){const valid=values.filter(Number.isFinite);let min=Math.min(0,...valid),max=Math.max(0,...valid);if(min===max){max=min+1;}const pad=(max-min)*.15;return {min:min<0?min-pad:0,max:max>0?max+pad:0};}
function axes(min,max,w=650,h=270){const l=52,r=w-23,top=27,b=h-40;let svg='';for(let i=0;i<5;i++){const y=top+(b-top)*i/4,val=max-(max-min)*i/4;svg+=`<line x1="${l}" x2="${r}" y1="${y}" y2="${y}" stroke="#eaf0e3" stroke-dasharray="3 4"/><text x="${l-11}" y="${y+4}" text-anchor="end">${shortNumber(val)}</text>`;}return {svg,l,r,top,b,y:v=>b-(v-min)/(max-min)*(b-top)};}
function lineChart(series,title,id){const list=series.slice(0,30);if(!list.length||!list.some(g=>Number.isFinite(g.value)))return emptySVG(t('没有可绘制的有效值','No valid values to plot'));const {min,max}=bounds(list.map(g=>g.value)),a=axes(min,max),step=(a.r-a.l)/Math.max(1,list.length-1),x=i=>list.length===1?(a.r+a.l)/2:a.l+i*step;let svg=svgStart(id,title)+`<defs><linearGradient id="${id}-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#9abc7f" stop-opacity=".3"/><stop offset="100%" stop-color="#9abc7f" stop-opacity=".02"/></linearGradient></defs>`+a.svg;let path='',segments=[],segment=[];list.forEach((g,i)=>{if(Number.isFinite(g.value)){segment.push([x(i),a.y(g.value)]);}else if(segment.length){segments.push(segment);segment=[];}});if(segment.length)segments.push(segment);segments.forEach(seg=>{const d=seg.map(([x,y],i)=>`${i?'L':'M'}${x},${y}`).join(' ');svg+=`<path d="${d} L${seg.at(-1)[0]},${a.y(0)} L${seg[0][0]},${a.y(0)} Z" fill="url(#${id}-fill)"/><path d="${d}" fill="none" stroke="#799b62" stroke-width="2.6" stroke-linejoin="round" stroke-linecap="round"/>`;});list.forEach((g,i)=>{if(Number.isFinite(g.value))svg+=`<circle cx="${x(i)}" cy="${a.y(g.value)}" r="3.3" fill="#fff" stroke="#799b62" stroke-width="2"/><circle cx="${x(i)}" cy="${a.y(g.value)}" r="12" fill="transparent" data-tip="${esc(`${display(g.key)} · ${nf(g.value,2)}`)}"/>`;if(i%Math.ceil(list.length/12)===0||i===list.length-1)svg+=`<text x="${x(i)}" y="${a.b+24}" text-anchor="middle">${esc(shortLabel(g.key,10))}</text>`;});return svg+'</svg>';}
function barChart(series,id,hist=false){const list=series.slice(0,30);if(!list.length||!list.some(g=>Number.isFinite(g.value)))return emptySVG(t('没有可绘制的有效值','No valid values to plot'));const {min,max}=bounds(list.map(g=>g.value)),a=axes(min,max),step=(a.r-a.l)/list.length,width=step*(hist?.87:.55);let svg=svgStart(id,t('分组柱状图','Grouped bar chart'))+a.svg;list.forEach((g,i)=>{const x=a.l+step*(i+.5),y=a.y(g.value||0),y0=a.y(0);if(Number.isFinite(g.value))svg+=`<rect x="${x-width/2}" y="${Math.min(y,y0)}" width="${width}" height="${Math.max(1,Math.abs(y0-y))}" rx="${hist?1:4}" fill="${hist?'#92b078':colors[i%colors.length]}" data-tip="${esc(`${display(g.key)} · ${nf(g.value,2)}`)}"/>`;if(i%Math.ceil(list.length/9)===0)svg+=`<text x="${x}" y="${a.b+24}" text-anchor="middle">${esc(shortLabel(g.key,10))}</text>`;});return svg+'</svg>';}
function donutGroups(groups){let list=groups.filter(g=>g.value>0).sort((a,b)=>b.value-a.value);return list.length>6?[...list.slice(0,5),{key:t('其他','Other'),value:list.slice(5).reduce((s,g)=>s+g.value,0)}]:list;}
function donutChart(groups,title,id){let list=donutGroups(groups);if(!list.length)return `<svg viewBox="0 0 350 242"><text x="175" y="120" text-anchor="middle">${t('没有可绘制的正值','No positive values to plot')}</text></svg>`;if(list.length>6)list=[...list.slice(0,5),{key:t('其他','Other'),value:list.slice(5).reduce((s,g)=>s+g.value,0)}];const total=list.reduce((a,g)=>a+g.value,0),cx=175,cy=119,r=79,circ=2*Math.PI*r;let svg=svgStart(id,title,350,242)+`<circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="#f0f3e9" stroke-width="27"/>`,offset=0;list.forEach((g,i)=>{const len=g.value/total*circ;svg+=`<circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="${colors[i%colors.length]}" stroke-width="27" stroke-dasharray="${Math.max(0,len-3)} ${circ-len+3}" stroke-dashoffset="${-offset}" transform="rotate(-90 ${cx} ${cy})" data-tip="${esc(`${display(g.key)} · ${nf(g.value,2)} (${nf(g.value/total*100,1)}%)`)}"/>`;offset+=len;});svg+=`<text x="${cx}" y="${cy-12}" text-anchor="middle" style="font-size:10px;fill:#a0aa92">${t('总计','TOTAL')}</text><text x="${cx}" y="${cy+17}" text-anchor="middle" style="font-size:25px;fill:#3e5839;font-weight:600">${shortNumber(total)}</text><text x="${cx}" y="${cy+37}" text-anchor="middle" style="font-size:9px">${esc(title||'')}</text></svg>`;return svg;}
function scatterChart(rows,x,y){const pts=rows.filter(r=>E.number(r[x])&&E.number(r[y])).slice(0,2000);if(!pts.length)return emptySVG(t('散点图需要两个数值字段','Scatter plots require two numeric columns'));const bx=bounds(pts.map(r=>Number(r[x]))),by=bounds(pts.map(r=>Number(r[y]))),a=axes(by.min,by.max),sx=v=>a.l+(v-bx.min)/(bx.max-bx.min)*(a.r-a.l);let svg=svgStart('custom-chart',`${label(x)} × ${label(y)}`)+a.svg;for(let i=0;i<5;i++){const v=bx.min+(bx.max-bx.min)*i/4;svg+=`<text x="${sx(v)}" y="${a.b+24}" text-anchor="middle">${shortNumber(v)}</text>`;}pts.forEach(r=>svg+=`<circle cx="${sx(Number(r[x]))}" cy="${a.y(Number(r[y]))}" r="4" fill="#86a46c" fill-opacity=".55" data-tip="${esc(`${label(x)}: ${nf(r[x],2)} · ${label(y)}: ${nf(r[y],2)}`)}"/>`);return svg+'</svg>';}
function histogram(rows,c){const vals=rows.map(r=>r[c]).filter(E.number).map(Number);if(!vals.length)return emptySVG(t('没有数值可生成直方图','No numeric values for the histogram'));let min=Math.min(...vals),max=Math.max(...vals);if(min===max)max=min+1;const bins=Math.min(15,Math.max(4,Math.ceil(Math.sqrt(vals.length)))),width=(max-min)/bins;const list=Array.from({length:bins},(_,i)=>({key:`${shortNumber(min+i*width)}–${shortNumber(min+(i+1)*width)}`,value:0}));vals.forEach(v=>list[Math.min(bins-1,Math.floor((v-min)/width))].value++);return barChart(list,'custom-chart',true);}
function customChart(){const c=state.chart,rows=state.data.rows;if(!validCols().length)return emptySVG(t('导入数值字段以生成图表','Import numeric columns to create charts'));if(c.type==='scatter')return scatterChart(rows,c.x,c.y);if(c.type==='histogram')return histogram(rows,c.y);const series=chartSeries(rows,c.x,c.y,c.agg,c.group);if(c.type==='line')return lineChart(series,label(c.y),'custom-chart');if(c.type==='bar')return barChart(series,'custom-chart');return donutChart(series,label(c.y),'custom-chart');}
